#define BUCKETS 7
typedef struct ChainNode {
    int key, value;
    struct ChainNode* next;
} ChainNode;

int hash(int key) { return key % BUCKETS; }

void insert(ChainNode* table[], int key, int value) {
    int idx = hash(key);
    ChainNode* n = malloc(sizeof(ChainNode));
    n->key = key; n->value = value;
    n->next = table[idx]; // insert at head of this bucket's chain
    table[idx] = n;
}

